#!/usr/bin/env bash
# Character C-02 (male) — replaces C-01 (D-058). Same file names as before so web/ imports keep working.
G="$(cd "$(dirname "$0")" && pwd)/genref.sh"
cd "$(dirname "$0")/../../../.."
RM=design/ring-master; R4=$RM/04-three-quarter-outer.png; M=design/assets/v1/masters; H=design/assets/v1/home
CHAR=$M/C-02-character.png
run(){ [[ -f "$2" ]] && { echo "SKIP $2"; return; }; "$G" "$@" || echo "FAIL $2"; }
STYLE="Real editorial lifestyle photograph, not a 3D render, shot on a full-frame camera with a 50 mm or 85 mm lens, natural light only, true-to-life skin texture with natural pores, warm natural grade matching a warm cream and sage palette (cream plaster, oak, linen, soft green leaves, warm sunlight with leaf shadows), soft film-like tonality, fine grain. Calm, quiet, candid, not posed. The person is the SAME man as in the attached character reference: same face, hair, beard, skin tone and oatmeal linen shirt. The face may be visible but natural and candid, never looking into the camera; the ring stays the clear focal point."
RING="He wears the smart ring from the attached ring reference on the INDEX finger of his LEFT hand, sitting between the knuckles, clearly visible: a slim smooth domed polished silver band about 7 mm wide with thin bright chamfered edges, realistic small scale on the finger, not thick or bulbous. The thumb and other fingers are bare."
ANAT="Every visible hand is anatomically correct with exactly five digits: one thumb and four separate fingers, natural joints and proportions, masculine hands with short clean nails."
AVOID="Avoid: looking into the camera, posed smile, ring on the thumb or on the wrong hand, oversized or bulbous ring, extra rings, watches, bracelets, other jewelry, interlaced fingers, fists, extra or missing fingers, fused fingers, glowing lights, CGI or plastic skin, HDR, oversaturated colors, lens flare, vignette, text, logos, brand marks, phone screens, numbers, scores, charts, posed model look."
SZ="--size 1080x1536"; S2="--size 1232x1536"
# 0) character master
run "Character reference portrait for a lifestyle series, real photograph, not a render. A man in his early-to-mid 30s with warm light-medium skin, short dark brown hair slightly tousled, a short neatly trimmed beard, calm kind eyes, wearing a relaxed oatmeal linen shirt with the top button open and sleeves slightly rolled. Half-body, three-quarter view, calm natural expression looking slightly off-camera. His LEFT hand rests lightly on his chest near the collar, back of the hand toward the camera, fingers relaxed and slightly apart, so the smart ring from the attached reference is clearly visible on his LEFT INDEX finger: slim smooth domed polished silver band about 7 mm wide, thin bright chamfered edges. Soft warm window light with gentle leaf shadows on a cream plaster wall behind. 4:5. $ANAT Avoid: other jewelry, watches, posed smile, HDR, CGI skin, text." $CHAR $S2 --ref $R4
# 1) Sleep section
run "$STYLE 'Last night, in one view.' Early morning just after waking, about 06:45. He lies in bed on his back on rumpled oatmeal linen bedding, eyes softly open, calm and rested, head on the pillow. His LEFT hand rests open and relaxed on the duvet over his chest, back of the hand up, fingers gently apart, the silver ring on the left index finger catching the first warm light. Pale cool dawn light through a sheer linen curtain, with a first band of warm sun and soft leaf shadows on the cream plaster wall above the bed. Shot from slightly above the bed, medium close, the hand and ring sharp in the lower foreground, his face softly in the upper part. Quiet, hushed. Vertical 4:5. $ANAT $RING $AVOID" $H/S2p-01-last-night.png $S2 --ref $R4 --ref $CHAR &
run "$STYLE 'Patterns, not scores.' Mid-morning calm. He sits relaxed on a low linen sofa by a tall window, holding a ceramic cup of tea in both hands at chest height, looking out of the window with an unhurried expression; nothing to check, no phone in sight. His LEFT hand wraps the front of the handle-less cup, back of the hand toward the camera, thumb on the near side and four fingers around the cup, the silver ring on the left index finger clearly visible. Warm morning sunlight about 4800K with leaf shadows across the cream wall, his shirt and the cushions. Medium shot from the side, slightly in front. Vertical 4:5. $ANAT $RING $AVOID" $H/S2p-02-patterns.png $S2 --ref $R4 --ref $CHAR &
wait
# 2) Activity and rest
run "$STYLE 07:40, Moving, a 25-minute morning walk. Candid medium shot from the side of him walking along a quiet tree-lined path in low warm early-morning sun, about 3600K, face in soft natural profile. His LEFT arm swings naturally forward mid-stride, the hand relaxed and open with fingers slightly apart in the sharp foreground, the silver ring catching the low sun; dappled leaf shadows on the linen sleeve; path and greenery softly out of focus. Vertical 5:7. $ANAT $RING $AVOID" $H/S3p-0740-moving-walk.png $SZ --ref $R4 --ref $CHAR &
run "$STYLE 09:00, Resting, 40 minutes of quiet focus. Indoors at a light oak desk beside a window with a sheer linen curtain; warm leaf shadows on a cream plaster wall. He sits still, reading, his face softly visible looking down at the book. His LEFT hand rests flat and relaxed on the page of an open paper book, fingers slightly apart, the silver ring clearly visible in the sharp foreground; a ceramic cup of coffee nearby. Calm morning light about 5000K. Vertical 5:7. $ANAT $RING $AVOID Also avoid: readable text on the pages." $H/S3p-0900-resting-focus.png $SZ --ref $R4 --ref $CHAR &
run "$STYLE 10:30, Moving, a 15-minute stretch. Indoors by a sunny window, he stands and stretches both arms straight forward at shoulder height, palms facing down, fingers relaxed and slightly apart, like a gentle morning reach; seen from a three-quarter front angle so the back of his LEFT hand faces the camera with all five digits separated and visible, the silver ring clearly on the left index finger. Eyes softly closed, calm face. Bright mid-morning sunlight about 5200K, crisp leaf shadows across the cream wall and his linen shirt. Vertical 5:7, hands in the middle third. $ANAT $RING $AVOID" $H/S3p-1030-moving-stretch.png $SZ --ref $R4 --ref $CHAR &
wait
run "$STYLE 12:30, Resting, a 30-minute lunch. Outdoors at a small oak table under a tree, dappled midday light and leaf shadows across the table and his shirt. A simple ceramic bowl of salad and a glass of water; he holds a fork at rest in his right hand while his LEFT hand rests flat and relaxed on the table in the foreground, fingers slightly apart, the silver ring clearly visible. Medium shot at about 40 degrees; he is relaxed, looking away. Midday light about 5600K. Vertical 5:7. $ANAT $RING $AVOID" $H/S3p-1230-resting-lunch.png $SZ --ref $R4 --ref $CHAR &
run "$STYLE 15:30, Moving, stairs and errands. Closer medium shot from the waist up, outdoors beside weathered stone steps and a cream plaster wall with climbing ivy, he climbs the stairs in calm profile, carrying an undyed canvas tote with leafy greens and a baguette on his right shoulder. His LEFT hand holds a dark metal handrail in a natural grip seen from above and slightly in front: the palm rests on top of the rail, the four fingers curl over the far side, and the THUMB wraps around the near side and is clearly visible; the back of the hand faces the camera so the silver ring on the left index finger is clearly visible on top, sharp in the lower foreground. Warm afternoon sun from the right about 4200K, leaf shadows on the wall. Vertical 5:7. $ANAT $RING $AVOID Also avoid: missing thumb, reversed hand." $H/S3p-1530-moving-stairs.png $SZ --ref $R4 --ref $CHAR &
wait
echo PEOPLE C02 DONE
